<script setup lang="ts">
import type { TripEvent } from '~/types/trip'
const { title, activeDay, days, selectedEvents, dayTitle, crew, synced, addDay, addEvent } = useTrip()
const selectedEvent = ref<TripEvent | null>(null)
const editingTitle = ref(false)
const draftTitle = ref('')
function editTitle() { draftTitle.value = title.value; editingTitle.value = true }
function saveTitle() { title.value = draftTitle.value; editingTitle.value = false }
function cancelTitle() { editingTitle.value = false }
const showAddEvent = ref(false)
const showInvite = ref(false)
function selectEvent(event: TripEvent) { selectedEvent.value = event }
function submitEvent(input: { title: string; place: string; time: string; tag: string }) { addEvent(input); showAddEvent.value = false }
</script>
<template>
  <div class="app-shell"><header class="topbar"><NuxtLink class="brand" to="/"><span class="brand-mark">✦</span> roam</NuxtLink><nav><NuxtLink class="nav-active" to="/trip">My plans</NuxtLink><NuxtLink to="/trip-map">Map</NuxtLink></nav><div class="mobile-header-label">{{ title }}</div><div class="top-actions"><div class="avatar">JM</div><span class="user-name">Jordan Miller</span></div></header><main><section class="hero-row"><div><div class="eyebrow"><span class="live-dot"></span> Local-first workspace</div><div v-if="editingTitle" class="trip-title-editor"><input v-model="draftTitle" autofocus aria-label="Trip title" @keyup.enter="saveTitle" @keyup.esc="cancelTitle" /><button class="primary-btn" @click="saveTitle">Save</button><button class="ghost-btn" @click="cancelTitle">Cancel</button></div><button v-else class="trip-title" @click="editTitle" title="Edit trip title">{{ title }} <span>✎</span></button><p class="subtitle">Four friends, one easygoing trip. <span class="lock">⌁</span> Private to your group.</p></div><div class="hero-actions"><NuxtLink class="ghost-btn" to="/trip-map">⌖ View map</NuxtLink><button class="primary-btn" @click="showAddEvent = true">＋ Add event</button></div></section><section class="trip-meta"><div class="meta-item"><span class="meta-icon">◷</span><div><strong>Sep 18 — 21, 2024</strong><small>4 days · Pacific Time</small></div></div><div class="meta-item"><span class="meta-icon">♧</span><div><strong>{{ crew.length }} travelers</strong><small>All members can edit</small></div></div><div class="meta-item map-meta"><span class="meta-icon">⌖</span><div><strong>Los Angeles, CA</strong><small>12 saved places</small></div></div></section><TripTimeline :events="selectedEvents" :active-day="activeDay" :days="days" :day-title="dayTitle" :synced="synced" @day="activeDay = $event" @select="selectEvent" @add="showAddEvent = true" @add-day="addDay" /><section class="lower-grid"><div class="panel quick-panel"><div class="panel-heading"><div><div class="section-label">Trip pulse</div><h2>Keep it moving</h2></div></div><div class="pulse-row"><div><strong>3.2 km</strong><span>walking today</span></div><div><strong>$86</strong><span>shared costs</span></div><div><strong>72°</strong><span>at 2:00 pm</span></div></div></div><CrewList :members="crew" @invite="showInvite = true" /></section></main><div v-if="selectedEvent" class="overlay" @click.self="selectedEvent = null"><aside class="event-detail"><button class="close-btn" @click="selectedEvent = null">×</button><div class="section-label">Event detail</div><div class="event-detail-dot" :class="selectedEvent.tone"></div><h2>{{ selectedEvent.title }}</h2><p class="detail-place">⌖ {{ selectedEvent.place }}</p><div class="detail-block"><span class="section-label">Schedule</span><strong>{{ selectedEvent.time }} · {{ dayTitle }}</strong></div><div class="detail-block"><span class="section-label">Travel</span><strong>{{ selectedEvent.travelTime || 'Route details loading' }} · {{ selectedEvent.transport || 'Walking' }}</strong></div><div class="detail-block"><span class="section-label">Split bill</span><strong>{{ selectedEvent.bill.length ? `${selectedEvent.bill.length} items added` : 'No bill added' }}</strong><button class="primary-btn detail-action">Scan receipt</button></div><button class="primary-btn detail-action" @click="selectedEvent = null">Save details</button></aside></div><AddEventModal v-if="showAddEvent" @submit="submitEvent" @close="showAddEvent = false" /><InviteModal v-if="showInvite" :title="title" @close="showInvite = false" /><footer><span>roam · made for the people you travel with</span></footer></div>
</template>
